{
  "name": "@haiilo/opencode-haiilo-ai",
  "version": "0.4.2",
  "description": "Official Haiilo AI plugin for OpenCode — auth (Manual API Key + Okta Device Flow) and automatic model discovery",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc && cp -r src/prompts/ dist/prompts",
    "clean": "rm -rf dist",
    "rebuild": "npm run clean && npm run build",
    "build:plugin": "esbuild src/index.ts --bundle --platform=node --format=esm --loader:.json=json --outfile=dist/bundle.js && cp -r src/prompts/ dist/prompts && echo 'Plugin built to dist/'",
    "build:dev": "esbuild src/index.ts --bundle --platform=node --format=esm --loader:.json=json --outfile=dist/bundle.js && cp -r src/prompts/ dist/prompts && cp dist/bundle.js ~/.config/opencode/plugins/haiilo-ai-dev.js && rm -rf ~/.config/opencode/plugins/prompts && cp -r src/prompts ~/.config/opencode/plugins/prompts && echo 'Dev plugin deployed to ~/.config/opencode/plugins/haiilo-ai-dev.js'",
    "dev": "node --input-type=module -e \"import {execSync} from 'child_process'; import fs from 'fs'; import path from 'path'; const cfgPath = path.join(process.env.HOME, '.config/opencode/opencode.json'); const cfg = JSON.parse(fs.readFileSync(cfgPath, 'utf8')); const ts = new Date().toISOString().replace(/:/g,'-').replace(/\\..+/,''); const bakPath = cfgPath + '.bak-pre-dev-' + ts; fs.writeFileSync(bakPath, JSON.stringify(cfg, null, 2) + '\\n'); console.log('Backup written to ' + bakPath); const before = (cfg.plugin || []).length; cfg.plugin = (cfg.plugin || []).filter(p => !p.startsWith('@haiilo/opencode-haiilo-ai')); const removed = before - cfg.plugin.length; fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2) + '\\n'); if (removed > 0) console.log('Removed @haiilo/opencode-haiilo-ai entry from plugin array'); else console.log('No @haiilo/opencode-haiilo-ai entry was present in plugin array'); execSync('npm run build:dev', {stdio: 'inherit'});\"",
    "dev:stop": "node --input-type=module -e \"import fs from 'fs'; import path from 'path'; const cfgDir = path.join(process.env.HOME, '.config/opencode'); const cfgPath = path.join(cfgDir, 'opencode.json'); const devFile = path.join(cfgDir, 'plugins/haiilo-ai-dev.js'); const baks = fs.readdirSync(cfgDir).filter(f => f.startsWith('opencode.json.bak-pre-dev-')).sort(); if (baks.length === 0) { console.error('No dev backup found — cannot restore. Aborting.'); process.exit(1); } const bakPath = path.join(cfgDir, baks[baks.length - 1]); const bak = JSON.parse(fs.readFileSync(bakPath, 'utf8')); const originalEntry = (bak.plugin || []).find(p => p.startsWith('@haiilo/opencode-haiilo-ai')); const cfg = JSON.parse(fs.readFileSync(cfgPath, 'utf8')); cfg.plugin = (cfg.plugin || []).filter(p => !p.startsWith('@haiilo/opencode-haiilo-ai')); if (originalEntry) { cfg.plugin.push(originalEntry); console.log('Restored plugin entry: ' + originalEntry + ' (from ' + baks[baks.length - 1] + ')'); } else { console.log('Original backup had no @haiilo/opencode-haiilo-ai entry — none restored'); } fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2) + '\\n'); if (fs.existsSync(devFile)) { fs.unlinkSync(devFile); console.log('Removed ' + devFile); } else { console.log('Dev plugin file was already gone: ' + devFile); } const promptsSrcDir = path.join(process.cwd(), 'src/prompts'); const promptsDestDir = path.join(cfgDir, 'plugins/prompts'); if (fs.existsSync(promptsSrcDir) && fs.existsSync(promptsDestDir)) { const devPromptFiles = fs.readdirSync(promptsSrcDir); for (const file of devPromptFiles) { const destPath = path.join(promptsDestDir, file); if (fs.existsSync(destPath)) { fs.unlinkSync(destPath); console.log('Removed dev prompt: ' + destPath); } } } console.log('Dev mode stopped. Restart OpenCode to use the published npm version.');\"",
    "prepublishOnly": "npm run build && esbuild src/index.ts --bundle --platform=node --format=esm --loader:.json=json --outfile=dist/bundle.js && cp -r src/prompts/ dist/prompts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "haiilo",
    "okta",
    "oauth2",
    "device-flow",
    "model-discovery",
    "authentication"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "dependencies": {
    "@opencode-ai/plugin": "*",
    "open": "^10.0.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "esbuild": "^0.28.0",
    "typescript": "^5.0.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
